import urllib.request,json
base='https://raw.githubusercontent.com/openmm/openmm/53770948682c40bd460b39830d4e0f0fd3a4b868/'
for p in ['README.md','docs-source/licenses/Licenses.txt','docs-source/usersguide/introduction.rst','docs-source/usersguide/application/01_getting_started.rst','examples/benchmark.py','examples/5dfr_solv-cube_equil.pdb']:
 try:
  b=urllib.request.urlopen(base+p).read()
  import hashlib
  print('\\nPATH',p,'BYTES',len(b),'SHA256',hashlib.sha256(b).hexdigest())
  if p.endswith('.pdb'): print('ATOMS',sum(x.startswith((b'ATOM  ',b'HETATM')) for x in b.splitlines()))
  elif p.endswith('benchmark.py'): pass
  else: print(b.decode()[:24000])
 except Exception as e: print(p,str(e))
PY"

