import urllib.request,json
base='https://raw.githubusercontent.com/openmm/openmm/53770948682c40bd460b39830d4e0f0fd3a4b868/'
u='https://api.github.com/repos/openmm/openmm/contents/examples?ref=8.2.0'
print([x['name'] for x in json.load(urllib.request.urlopen(u))])
for p in ['docs-source/usersguide/library/01_introduction.rst','docs-source/licenses/LGPL.txt','wrappers/python/openmm/app/data/amber99sb.xml','wrappers/python/openmm/app/data/tip3p.xml','docs-source/usersguide/theory/05_other_features.rst']:
 try:
  b=urllib.request.urlopen(base+p).read(); s=b.decode(errors='replace')
  print('\\nPATH',p)
  if p.endswith('.xml'):
   import hashlib
   print('BYTES',len(b),'SHA256',hashlib.sha256(b).hexdigest());print(s[:1400])
  elif 'other_features' in p:
   start=s.find('Random'); print(s[start:start+7000])
  else: print(s[:6500])
 except Exception as e: print(e)
PY"

